class Solution {
    public int numPrimeArrangements(int n){
        boolean[] prime=new boolean[n+1];
        Arrays.fill(prime,true);
        if(n>=0)prime[0]=false;
        if(n>=1)prime[1]=false;
        for(int value=2;value*value<=n;value++)if(prime[value])for(int multiple=value*value;multiple<=n;multiple+=value)prime[multiple]=false;
        int count=0;
        for(boolean value:prime)if(value)count++;
        long answer=1,mod=1000000007L;
        for(int value=2;value<=count;value++)answer=answer*value%mod;
        for(int value=2;value<=n-count;value++)answer=answer*value%mod;
        return (int)answer;
    }
}

code.kotlin:
class Solution {
    fun numPrimeArrangements(n:Int):Int{
        val prime=BooleanArray(n+1){
            true
        };
        prime[0]=false;
        if(n>=1)prime[1]=false;
        var value=2;
        while(value*value<=n){
            if(prime[value])for(multiple in value*value..n step value)prime[multiple]=false;
            value++
        };
        val count=prime.count{
            it
        };
        val mod=1000000007L;
        var answer=1L;
        for(number in 2..count)answer=answer*number%mod;
        for(number in 2..n-count)answer=answer*number%mod;
        return answer.toInt()
    }
}

